// TRANSFORM & PREPARE: Convert raw API data to structured context
// This context will be stored in DB for LLM reasoning

const transportData = $('Fetch Train Connections').first().json;
const weatherData = $('Fetch Weather').first().json;
const calendarData = $('Fetch Calendar Events').all();

const sessionToken = `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const snapshotId = `snapshot_${Date.now()}`;

// Parse transport connections with full details
const connections = (transportData.journeys || []).map((journey, i) => {
  const leg = journey.legs?.[0] || {};
  const isCancelled = leg.cancelled === true;
  const delaySeconds = leg.departureDelay || 0;
  const delayMinutes = Math.round(delaySeconds / 60);

  let status = 'ON_TIME';
  if (isCancelled) status = 'CANCELLED';
  else if (delayMinutes >= 10) status = 'DELAYED';
  else if (delayMinutes > 0) status = 'MINOR_DELAY';

  return {
    id: `conn_${i + 1}`,
    departure: leg.departure,
    arrival: leg.arrival,
    plannedDeparture: leg.plannedDeparture,
    plannedArrival: leg.plannedArrival,
    line: leg.line?.name || 'RE4',
    operator: leg.line?.operator?.name || 'DB Regio',
    origin: leg.origin?.name || 'Hamburg Hbf',
    destination: leg.destination?.name || 'Bremen Hbf',
    status,
    delayMinutes,
    isCancelled,
    platform: leg.departurePlatform || null,
    remarks: (leg.remarks || []).map(r => ({ type: r.type, text: r.text }))
  };
});

// Parse weather with hourly breakdown
const hourly = weatherData.hourly || {};
const currentHour = new Date().getHours();
const weatherHourly = [];

for (let i = currentHour; i < Math.min(currentHour + 6, (hourly.time || []).length); i++) {
  weatherHourly.push({
    hour: i,
    time: hourly.time?.[i],
    precipitation: hourly.precipitation?.[i] || 0,
    weatherCode: hourly.weathercode?.[i],
    temperature: hourly.temperature_2m?.[i]
  });
}

const hasRain = weatherHourly.some(h => h.precipitation > 0.5);
const rainStartHour = weatherHourly.find(h => h.precipitation > 0.5);

const weatherContext = {
  currentTemperature: hourly.temperature_2m?.[currentHour],
  condition: hasRain ? 'rain' : 'clear',
  rainStartsAt: rainStartHour ? `${String(rainStartHour.hour).padStart(2, '0')}:00` : null,
  hourlyForecast: weatherHourly
};

// Parse calendar events
const events = calendarData.map(item => {
  const event = item.json;
  const startTime = event.start?.dateTime || event.start?.date;
  return {
    id: event.id,
    title: event.summary || 'Meeting',
    startTime,
    endTime: event.end?.dateTime || event.end?.date,
    localTime: startTime ? new Date(startTime).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }) : null,
    location: event.location || null,
    isAllDay: !event.start?.dateTime
  };
}).filter(e => !e.isAllDay);

const nextMeeting = events[0] || null;

// Detect disruptions
const hasDisruption = connections.some(c => c.isCancelled || c.delayMinutes >= 10);

// Build complete context snapshot (stored in DB)
const contextSnapshot = {
  id: snapshotId,
  sessionToken,
  fetchedAt: new Date().toISOString(),

  route: {
    from: 'Hamburg Hbf',
    to: 'Bremen Hbf',
    preferredLine: 'RE4',
    fromId: '8002549',
    toId: '8000050'
  },

  transport: {
    connections,
    summary: {
      totalConnections: connections.length,
      cancelledCount: connections.filter(c => c.isCancelled).length,
      delayedCount: connections.filter(c => c.delayMinutes >= 10).length,
      nextAvailable: connections.find(c => !c.isCancelled),
      nextStable: connections.find(c => !c.isCancelled && c.delayMinutes < 5)
    }
  },

  weather: weatherContext,

  calendar: {
    events,
    nextMeeting,
    hasMeetingsToday: events.length > 0
  },

  userPreferences: {
    homeOfficeAllowed: true,
    avoidWaitingOutdoors: hasRain,
    preferredArrivalBuffer: 30
  },

  analysis: {
    hasDisruption,
    hasCancellation: connections.some(c => c.isCancelled),
    hasSignificantDelay: connections.some(c => c.delayMinutes >= 10),
    hasRain,
    urgency: hasDisruption ? 'high' : (hasRain ? 'medium' : 'low')
  }
};

return { contextSnapshot };

// BUILD DECISION PROMPT: LLM reasons over stored context

const contextSnapshot = $('Build Context Snapshot').first().json.contextSnapshot;
const lastDecision = $('Get Last Decision').first()?.json || null;

const systemPrompt = `You are a commute decision assistant for Hamburg → Bremen via RE4 train.

ROLE: Analyze the provided context data and recommend ONE clear action.

PRINCIPLE: "This app tells you what to do" — reduce stress, avoid pointless waiting.

DECISION TYPES:
- WORK_FROM_HOME_TEMPORARILY: Disruption now, stable connection later, user can work from home
- WAIT_AND_LEAVE_LATER: Minor delay, worth waiting briefly  
- LEAVE_NOW: Current connection is best option
- LEAVE_EARLIER_THAN_USUAL: Avoid rain or anticipated disruptions

DECISION RULES:
1. Cancelled trains = NEVER recommend
2. Delays >10min = significant, avoid if alternative exists
3. Rain = avoid outdoor waiting at station
4. User MUST arrive before their next meeting (with buffer)
5. If homeOfficeAllowed=true, prefer WORK_FROM_HOME_TEMPORARILY over waiting at station
6. Recommend STABLE connections, not just fastest
7. Consider the full context: weather, calendar, all connections`;

const userPrompt = `CONTEXT SNAPSHOT:
${JSON.stringify(contextSnapshot, null, 2)}

${lastDecision ? `PREVIOUS DECISION: ${lastDecision.decision} (departure: ${JSON.parse(lastDecision.recommendation || '{}').recommendedDepartureTime})` : 'No previous decision.'}

Generate a decision. OUTPUT (strict JSON, no markdown):
{
  "decision": "WORK_FROM_HOME_TEMPORARILY|WAIT_AND_LEAVE_LATER|LEAVE_NOW|LEAVE_EARLIER_THAN_USUAL",
  "confidence": 0.0-1.0,
  "currentUpdates": [
    {"type":"transport|weather","icon":"train|rain|sun|warning","title":"short title","message":"details","severity":"low|medium|high","line":"RE4"}
  ],
  "recommendation": {
    "action": "What to do now (imperative)",
    "primaryInstruction": "Take the RE4 at HH:MM",
    "recommendedDepartureTime": "HH:MM",
    "icon": "train|home|clock",
    "reasonShort": "One sentence why",
    "reasonLong": "Full explanation with details from context"
  },
  "explanationShort": "Push notification text (max 100 chars)",
  "explanationLong": "Full voice explanation (2-3 sentences, friendly tone)",
  "uiHints": {"highlightAction":true,"playVoiceSummary":true,"confidenceIndicator":"high|medium|low"}
}`;

return {
  systemPrompt,
  userPrompt,
  contextSnapshot,
  lastDecision
};

// PARSE: Extract AgentDecision from Gemini response

const geminiResponse = $input.first().json;
const previousData = $('Build Decision Prompt').first().json;
const contextSnapshot = previousData.contextSnapshot;

try {
  const text = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error('No text in Gemini response');

  const decision = JSON.parse(text);

  if (!decision.decision || !decision.recommendation || !decision.explanationShort) {
    throw new Error('Invalid decision structure');
  }

  return {
    id: `dec_${Date.now()}`,
    ...decision,
    sessionToken: contextSnapshot.sessionToken,
    snapshotId: contextSnapshot.id,
    created_at: new Date().toISOString()
  };
} catch (error) {
  return {
    id: `dec_fallback_${Date.now()}`,
    decision: 'LEAVE_NOW',
    confidence: 0.5,
    sessionToken: contextSnapshot.sessionToken,
    snapshotId: contextSnapshot.id,
    currentUpdates: [{
      type: 'transport',
      icon: 'warning',
      title: 'Status check recommended',
      message: 'Please verify current train status',
      severity: 'medium'
    }],
    recommendation: {
      action: 'Check current status',
      primaryInstruction: 'Verify RE4 status on DB app',
      recommendedDepartureTime: 'now',
      icon: 'train',
      reasonShort: 'Unable to generate recommendation',
      reasonLong: 'The system could not generate a recommendation. Please check the Deutsche Bahn app.'
    },
    explanationShort: 'Check DB app for current status',
    explanationLong: 'I could not generate a decision. Please check the transport status manually.',
    uiHints: { highlightAction: false, playVoiceSummary: false, confidenceIndicator: 'low' },
    _error: error.message,
    created_at: new Date().toISOString()
  };
}

// UPLOAD AUDIO: Store MP3 and get URL
// In production, upload to Supabase Storage or S3

const decision = $('Parse Decision').first().json;
const audioData = $input.first().binary?.data;

// Generate audio URL (in production: upload to storage and get URL)
const audioFilename = `audio_${decision.id}.mp3`;
const audioUrl = `https://storage.supabase.co/v1/object/public/audio/${audioFilename}`;

// For now, we'll store a reference. In production:
// 1. Upload audioData to Supabase Storage
// 2. Get the public URL
// 3. Store URL with decision

return {
  ...decision,
  audioUrl,
  audioFilename,
  audioGenerated: true
};

