// USER REPLY HANDLER: Parse incoming request

const body = $input.first().json.body || $input.first().json;
const sessionToken = body.sessionToken;
const userMessage = body.message || body.text || '';
const replyType = body.replyType || 'question';
const modifyConstraints = body.modifyConstraints || {};

if (!sessionToken) {
  throw new Error('Missing sessionToken in request');
}

return {
  sessionToken,
  userMessage,
  replyType,
  modifyConstraints,
  receivedAt: new Date().toISOString()
};

// BUILD REPLY PROMPT: LLM reasons over STORED context (no new API calls)

const replyData = $('Parse User Reply').first().json;
const decisionRecord = $('Get Decision by Session').first()?.json || {};
const contextRecord = $('Get Context Snapshot').first()?.json || {};

// Parse stored JSON fields
const transport = JSON.parse(contextRecord.transport || '{}');
const weather = JSON.parse(contextRecord.weather || '{}');
const calendar = JSON.parse(contextRecord.calendar || '{}');
const originalDecision = {
  decision: decisionRecord.decision,
  recommendation: JSON.parse(decisionRecord.recommendation || '{}'),
  explanationLong: decisionRecord.explanation_long
};

const systemPrompt = `You are a helpful commute assistant. The user is asking about their commute.

You have access to the STORED CONTEXT from when the recommendation was made:

TRANSPORT DATA:
${JSON.stringify(transport, null, 2)}

WEATHER DATA:
${JSON.stringify(weather, null, 2)}

CALENDAR DATA:
${JSON.stringify(calendar, null, 2)}

ORIGINAL RECOMMENDATION:
- Decision: ${originalDecision.decision}
- Recommended departure: ${originalDecision.recommendation.recommendedDepartureTime}
- Reason: ${originalDecision.recommendation.reasonLong}

INSTRUCTIONS:
1. Answer the user's question using the stored context data
2. If they ask to modify (leave later/earlier), find a suitable connection from the stored transport data
3. Be conversational but concise
4. Always reference specific data (times, delays, weather conditions)
5. If asked about something not in the context, say you don't have that information`;

let userPrompt;
if (replyData.replyType === 'modify') {
  const delayMinutes = replyData.modifyConstraints.minDepartureDelayMinutes || 0;
  userPrompt = `User request: "${replyData.userMessage}"

They want to modify their departure. Constraints: leave at least ${delayMinutes} minutes later than original recommendation.

Find a suitable connection from the STORED transport data. Do NOT fetch new data.

Respond with JSON:
{
  "responseText": "Your conversational response acknowledging the change",
  "newRecommendation": {
    "action": "Updated action",
    "primaryInstruction": "Take the RE4 at HH:MM",
    "recommendedDepartureTime": "HH:MM",
    "reasonShort": "Why this works",
    "reasonLong": "Full explanation"
  }
}`;
} else {
  userPrompt = `User question: "${replyData.userMessage}"

Answer using the stored context data. Be specific with times and conditions.

Respond with JSON:
{
  "responseText": "Your helpful answer based on the stored data",
  "newRecommendation": null
}`;
}

return {
  systemPrompt,
  userPrompt,
  replyData,
  originalDecision,
  sessionToken: replyData.sessionToken
};

// PARSE REPLY: Extract response from Gemini

const geminiResponse = $input.first().json;
const previousData = $('Build Reply Prompt').first().json;

try {
  const text = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error('No text in Gemini response');

  const response = JSON.parse(text);

  return {
    responseText: response.responseText || 'I understood your request.',
    newRecommendation: response.newRecommendation || null,
    sessionToken: previousData.sessionToken,
    replyType: previousData.replyData.replyType
  };
} catch (error) {
  return {
    responseText: 'I understood your question. Based on the current data, I recommend following the original plan.',
    newRecommendation: null,
    sessionToken: previousData.sessionToken,
    replyType: previousData.replyData.replyType,
    _error: error.message
  };
}

// BUILD FINAL RESPONSE: Include audio URL

const replyData = $('Parse Reply').first().json;
const audioData = $input.first().binary?.data;

const messageId = `msg_${Date.now()}`;
const audioFilename = `audio_${messageId}.mp3`;
const audioUrl = `https://storage.supabase.co/v1/object/public/audio/${audioFilename}`;

// Build response for app
return {
  success: true,
  message: {
    id: messageId,
    role: 'assistant',
    text: replyData.responseText,
    audioUrl: audioUrl,
    created_at: new Date().toISOString()
  },
  updatedRecommendation: replyData.newRecommendation,
  sessionToken: replyData.sessionToken
};
